import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import {
  verifyDiscordRequest,
  type Interaction,
  jsonResponse,
  ephemeral,
} from "./discord.ts";
import { handleCommand, handleComponent } from "./commands.ts";
import { loadEnv } from "./config.ts";

Deno.serve(async (req) => {
  if (req.method !== "POST") {
    return new Response("Method not allowed", { status: 405 });
  }

  let env;
  try {
    env = await loadEnv();
  } catch (err) {
    return new Response(String(err), { status: 500 });
  }

  const { valid, body } = await verifyDiscordRequest(req, env.publicKey);
  if (!valid) {
    return new Response("Invalid request signature", { status: 401 });
  }

  const interaction = JSON.parse(body) as Interaction;

  if (interaction.type === 1) {
    return jsonResponse({ type: 1 });
  }

  try {
    if (interaction.type === 2) {
      const response = await handleCommand(interaction, env);
      return jsonResponse(response);
    }

    if (interaction.type === 3) {
      const response = await handleComponent(interaction, env);
      return jsonResponse(response);
    }

    return jsonResponse(ephemeral("Unsupported interaction type."));
  } catch (err) {
    console.error(err);
    return jsonResponse(
      ephemeral(`Something went wrong: ${err instanceof Error ? err.message : "error"}`),
    );
  }
});

import { createClient } from "jsr:@supabase/supabase-js@2";

const APPLICATION_ID = "1536251834203770941";
const DEFAULT_PUBLIC_KEY =
  "cb8edf355b81013b7f84bb228a5df074a5253b2680f42f8ccbbc661b434fc1a5";

export type BotEnv = {
  token: string;
  publicKey: string;
  applicationId: string;
  guildId: string;
  ticketCategoryId?: string;
  updatesChannelId?: string;
  welcomeChannelId?: string;
  rulesChannelId?: string;
  supportChannelId?: string;
  staffRoleId?: string;
};

async function vaultSetting(name: string): Promise<string | undefined> {
  const url = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) return undefined;

  const supabase = createClient(url, key, { auth: { persistSession: false } });
  const { data, error } = await supabase.rpc("discord_bot_setting", {
    setting_name: name,
  });
  if (error || !data) return undefined;
  return String(data);
}

async function setting(name: string, fallback?: string): Promise<string | undefined> {
  return Deno.env.get(name) ?? (await vaultSetting(name)) ?? fallback;
}

export async function loadEnv(): Promise<BotEnv> {
  const token = await setting("DISCORD_BOT_TOKEN");
  const publicKey = await setting("DISCORD_PUBLIC_KEY", DEFAULT_PUBLIC_KEY);

  if (!token || !publicKey) {
    throw new Error("DISCORD_BOT_TOKEN and DISCORD_PUBLIC_KEY are required");
  }

  return {
    token,
    publicKey,
    applicationId: (await setting("DISCORD_APPLICATION_ID")) ?? APPLICATION_ID,
    guildId: (await setting("DISCORD_GUILD_ID")) ?? "",
    ticketCategoryId: await setting("DISCORD_TICKET_CATEGORY_ID"),
    updatesChannelId: await setting("DISCORD_UPDATES_CHANNEL_ID"),
    welcomeChannelId: await setting("DISCORD_WELCOME_CHANNEL_ID"),
    rulesChannelId: await setting("DISCORD_RULES_CHANNEL_ID"),
    supportChannelId: await setting("DISCORD_SUPPORT_CHANNEL_ID"),
    staffRoleId: await setting("DISCORD_STAFF_ROLE_ID"),
  };
}

export async function saveVaultSetting(name: string, value: string): Promise<void> {
  const url = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) return;

  const supabase = createClient(url, key, { auth: { persistSession: false } });
  await supabase.rpc("discord_bot_upsert_setting", {
    setting_name: name,
    setting_value: value,
  });
}

const DISCORD_API = "https://discord.com/api/v10";

export function hexToBytes(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.slice(i, i + 2), 16);
  }
  return bytes;
}

export async function verifyDiscordRequest(
  request: Request,
  publicKeyHex: string,
): Promise<{ valid: boolean; body: string }> {
  const signature = request.headers.get("X-Signature-Ed25519");
  const timestamp = request.headers.get("X-Signature-Timestamp");
  const body = await request.text();

  if (!signature || !timestamp) {
    return { valid: false, body };
  }

  const message = new TextEncoder().encode(timestamp + body);
  const sig = hexToBytes(signature);
  const key = hexToBytes(publicKeyHex);

  const cryptoKey = await crypto.subtle.importKey(
    "raw",
    key,
    { name: "Ed25519", namedCurve: "Ed25519" },
    false,
    ["verify"],
  );

  const valid = await crypto.subtle.verify("Ed25519", cryptoKey, sig, message);
  return { valid, body };
}

export async function discordRequest(
  token: string,
  path: string,
  init: RequestInit = {},
): Promise<Response> {
  const headers = new Headers(init.headers);
  headers.set("Authorization", `Bot ${token}`);
  if (init.body && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }

  return fetch(`${DISCORD_API}${path}`, { ...init, headers });
}

export async function discordJson<T>(
  token: string,
  path: string,
  init: RequestInit = {},
): Promise<T> {
  const res = await discordRequest(token, path, init);
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Discord API ${path}: ${res.status} ${text}`);
  }
  if (res.status === 204) {
    return undefined as T;
  }
  return (await res.json()) as T;
}

export type Interaction = {
  id: string;
  type: number;
  token: string;
  data?: {
    name?: string;
    options?: Array<{
      name: string;
      type: number;
      value?: string;
      options?: Interaction["data"]["options"];
    }>;
    custom_id?: string;
  };
  member?: {
    user: { id: string; username: string; global_name?: string };
    roles: string[];
    permissions: string;
  };
  user?: { id: string; username: string; global_name?: string };
  guild_id?: string;
  channel_id?: string;
  message?: { id: string };
};

export function interactionUser(interaction: Interaction) {
  return interaction.member?.user ?? interaction.user;
}

export function hasAdmin(interaction: Interaction): boolean {
  const perms = BigInt(interaction.member?.permissions ?? "0");
  return (perms & 8n) === 8n;
}

export function jsonResponse(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

export function ephemeral(content: string) {
  return {
    type: 4,
    data: { content, flags: 64 },
  };
}

export function channelMessage(content: string, embeds?: unknown[]) {
  return {
    type: 4,
    data: { content, embeds },
  };
}

export function deferredEphemeral() {
  return { type: 5, data: { flags: 64 } };
}

export async function followUp(
  token: string,
  applicationId: string,
  interactionToken: string,
  data: Record<string, unknown>,
) {
  await discordRequest(
    token,
    `/webhooks/${applicationId}/${interactionToken}`,
    { method: "POST", body: JSON.stringify(data) },
  );
}

export async function editOriginal(
  token: string,
  applicationId: string,
  interactionToken: string,
  data: Record<string, unknown>,
) {
  await discordRequest(
    token,
    `/webhooks/${applicationId}/${interactionToken}/messages/@original`,
    { method: "PATCH", body: JSON.stringify(data) },
  );
}

type UpdateType = "small" | "big";

export function updateEmbed(
  title: string,
  description: string,
  type: UpdateType,
  authorName?: string,
) {
  const isBig = type === "big";
  return {
    title: isBig ? `🚀 ${title}` : `📌 ${title}`,
    description,
    color: isBig ? 0x5865f2 : 0x57f287,
    footer: authorName
      ? { text: `Posted by ${authorName}` }
      : { text: "kdesa.stream updates" },
    timestamp: new Date().toISOString(),
  };
}

export function ticketOpenEmbed(subject: string, openerMention: string) {
  return {
    title: "Support ticket",
    description: [
      `${openerMention} opened this ticket.`,
      subject ? `\n**Subject:** ${subject}` : "",
      "",
      "Describe your issue here. Staff will reply when they can.",
      "Use **Close ticket** below or `/ticket-close` when you're done.",
    ].join("\n"),
    color: 0xfee75c,
  };
}

export function welcomeEmbed() {
  return {
    title: "Welcome to kdesa.stream",
    description: [
      "Thanks for joining the community server.",
      "",
      "• Read the rules in <#RULES>",
      "• Site issues or account help → open a ticket in <#SUPPORT>",
      "• Site updates get posted in <#UPDATES>",
      "",
      "Stream, browse manga, and hang out: **https://kdesa.stream**",
    ].join("\n"),
    color: 0x5865f2,
  };
}

export function rulesEmbed() {
  return {
    title: "Server rules",
    description: [
      "1. Be respectful — no harassment, slurs, or drama.",
      "2. No spam, self-promo, or unsolicited links.",
      "3. Don't share illegal streams, leaks, or piracy how-tos.",
      "4. Support tickets are for site/account issues — keep them on-topic.",
      "5. Staff decisions are final.",
      "",
      "Breaking rules may result in mutes or bans.",
    ].join("\n"),
    color: 0xed4245,
  };
}

export function replaceChannelPlaceholders(
  embed: ReturnType<typeof welcomeEmbed>,
  ids: { rules?: string; support?: string; updates?: string },
) {
  let description = embed.description ?? "";
  if (ids.rules) description = description.replace("<#RULES>", `<#${ids.rules}>`);
  if (ids.support) {
    description = description.replace("<#SUPPORT>", `<#${ids.support}>`);
  }
  if (ids.updates) {
    description = description.replace("<#UPDATES>", `<#${ids.updates}>`);
  }
  return { ...embed, description };
}

import { createClient } from "jsr:@supabase/supabase-js@2";
import {
  type Interaction,
  discordJson,
  followUp,
  editOriginal,
  interactionUser,
  hasAdmin,
  ephemeral,
} from "./discord.ts";
import {
  updateEmbed,
  ticketOpenEmbed,
  welcomeEmbed,
  rulesEmbed,
  replaceChannelPlaceholders,
} from "./embeds.ts";
import { saveVaultSetting } from "./config.ts";

type Env = {
  token: string;
  applicationId: string;
  guildId: string;
  ticketCategoryId?: string;
  updatesChannelId?: string;
  welcomeChannelId?: string;
  rulesChannelId?: string;
  supportChannelId?: string;
  staffRoleId?: string;
};

type DiscordChannel = { id: string; name: string; type: number };

function optionString(
  interaction: Interaction,
  name: string,
): string | undefined {
  const opt = interaction.data?.options?.find((o) => o.name === name);
  return typeof opt?.value === "string" ? opt.value : undefined;
}

function isStaff(interaction: Interaction, env: Env): boolean {
  if (hasAdmin(interaction)) return true;
  if (!env.staffRoleId) return hasAdmin(interaction);
  return interaction.member?.roles.includes(env.staffRoleId) ?? false;
}

function supabaseAdmin() {
  const url = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) throw new Error("Missing Supabase env");
  return createClient(url, key, { auth: { persistSession: false } });
}

async function nextTicketName(token: string, guildId: string): Promise<string> {
  const channels = await discordJson<DiscordChannel[]>(
    token,
    `/guilds/${guildId}/channels`,
  );
  const nums = channels
    .map((c) => /^ticket-(\d+)$/.exec(c.name))
    .filter(Boolean)
    .map((m) => parseInt(m![1], 10));
  const next = nums.length ? Math.max(...nums) + 1 : 1;
  return `ticket-${String(next).padStart(3, "0")}`;
}

export async function handleCommand(
  interaction: Interaction,
  env: Env,
): Promise<Record<string, unknown>> {
  const name = interaction.data?.name;
  const user = interactionUser(interaction);
  if (!user || !interaction.guild_id) {
    return ephemeral("This command only works in a server.");
  }

  switch (name) {
    case "ticket":
      return handleTicket(interaction, env, user);
    case "ticket-close":
      return handleTicketClose(interaction, env, user);
    case "update":
      return handleUpdate(interaction, env, user);
    case "setup-server":
      return handleSetupServer(interaction, env, user);
    default:
      return ephemeral("Unknown command.");
  }
}

async function handleTicket(
  interaction: Interaction,
  env: Env,
  user: { id: string; username: string },
): Promise<Record<string, unknown>> {
  if (!env.ticketCategoryId) {
    return ephemeral(
      "Tickets are not configured yet. Run `/setup-server` (admin) or set DISCORD_TICKET_CATEGORY_ID.",
    );
  }

  const subject = optionString(interaction, "subject")?.slice(0, 200);
  const supabase = supabaseAdmin();

  const { data: existing } = await supabase
    .from("discord_tickets")
    .select("channel_id")
    .eq("guild_id", interaction.guild_id!)
    .eq("opener_discord_id", user.id)
    .eq("status", "open")
    .maybeSingle();

  if (existing?.channel_id) {
    return ephemeral(`You already have an open ticket: <#${existing.channel_id}>`);
  }

  const channelName = await nextTicketName(env.token, interaction.guild_id!);
  const channel = await discordJson<DiscordChannel>(
    env.token,
    `/guilds/${interaction.guild_id}/channels`,
    {
      method: "POST",
      body: JSON.stringify({
        name: channelName,
        type: 0,
        parent_id: env.ticketCategoryId,
        topic: `Ticket for ${user.username}${subject ? ` — ${subject}` : ""}`,
        permission_overwrites: [
          {
            id: interaction.guild_id,
            type: 0,
            deny: "1024",
          },
          {
            id: user.id,
            type: 1,
            allow: "3072",
          },
          ...(env.staffRoleId
            ? [{
              id: env.staffRoleId,
              type: 0,
              allow: "3072",
            }]
            : []),
        ],
      }),
    },
  );

  await supabase.from("discord_tickets").insert({
    guild_id: interaction.guild_id,
    channel_id: channel.id,
    opener_discord_id: user.id,
    subject: subject ?? null,
    status: "open",
  });

  const embed = ticketOpenEmbed(subject ?? "", `<@${user.id}>`);
  await discordJson(env.token, `/channels/${channel.id}/messages`, {
    method: "POST",
    body: JSON.stringify({
      content: `<@${user.id}>`,
      embeds: [embed],
      components: [{
        type: 1,
        components: [{
          type: 2,
          style: 4,
          label: "Close ticket",
          custom_id: "ticket_close",
        }],
      }],
    }),
  });

  return ephemeral(`Ticket created: <#${channel.id}>`);
}

async function handleTicketClose(
  interaction: Interaction,
  env: Env,
  user: { id: string; username: string },
): Promise<Record<string, unknown>> {
  const channelId = interaction.channel_id;
  if (!channelId) return ephemeral("Run this inside a ticket channel.");

  const supabase = supabaseAdmin();
  const { data: ticket } = await supabase
    .from("discord_tickets")
    .select("*")
    .eq("channel_id", channelId)
    .eq("status", "open")
    .maybeSingle();

  if (!ticket) {
    return ephemeral("This is not an open ticket channel.");
  }

  const canClose = ticket.opener_discord_id === user.id || isStaff(interaction, env);
  if (!canClose) {
    return ephemeral("Only the ticket opener or staff can close this.");
  }

  await supabase
    .from("discord_tickets")
    .update({ status: "closed", closed_at: new Date().toISOString() })
    .eq("id", ticket.id);

  await discordJson(env.token, `/channels/${channelId}`, {
    method: "DELETE",
  }).catch(() => undefined);

  return ephemeral("Ticket closed.");
}

async function handleUpdate(
  interaction: Interaction,
  env: Env,
  user: { id: string; username: string; global_name?: string },
): Promise<Record<string, unknown>> {
  if (!isStaff(interaction, env)) {
    return ephemeral("Only staff can post updates.");
  }

  if (!env.updatesChannelId) {
    return ephemeral(
      "Updates channel not configured. Run `/setup-server` or set DISCORD_UPDATES_CHANNEL_ID.",
    );
  }

  const title = optionString(interaction, "title");
  const description = optionString(interaction, "description");
  const type = (optionString(interaction, "type") ?? "small") as "small" | "big";

  if (!title || !description) {
    return ephemeral("Title and description are required.");
  }

  const displayName = user.global_name ?? user.username;
  const embed = updateEmbed(title, description, type, displayName);

  await discordJson(env.token, `/channels/${env.updatesChannelId}/messages`, {
    method: "POST",
    body: JSON.stringify({ embeds: [embed] }),
  });

  return ephemeral(`Update posted to <#${env.updatesChannelId}>. (No ping — tell me if you want one later.)`);
}

async function handleSetupServer(
  interaction: Interaction,
  env: Env,
  user: { id: string; username: string },
): Promise<Record<string, unknown>> {
  if (!hasAdmin(interaction)) {
    return ephemeral("You need Administrator to run server setup.");
  }

  const guildId = interaction.guild_id!;
  const deferred = { type: 5, data: { flags: 64 } };

  queueMicrotask(async () => {
    try {
      const created = await runServerSetup(env.token, guildId, env.applicationId);

      await saveVaultSetting("DISCORD_GUILD_ID", guildId);
      await saveVaultSetting("DISCORD_RULES_CHANNEL_ID", created.rulesId);
      await saveVaultSetting("DISCORD_WELCOME_CHANNEL_ID", created.welcomeId);
      await saveVaultSetting("DISCORD_UPDATES_CHANNEL_ID", created.updatesId);
      await saveVaultSetting("DISCORD_SUPPORT_CHANNEL_ID", created.supportId);
      await saveVaultSetting("DISCORD_TICKET_CATEGORY_ID", created.ticketCategoryId);

      await editOriginal(env.token, env.applicationId, interaction.token, {
        content: [
          "Server setup complete. Channel IDs saved to Supabase Vault.",
          "",
          `#rules <#${created.rulesId}>`,
          `#welcome <#${created.welcomeId}>`,
          `#updates <#${created.updatesId}>`,
          `#support <#${created.supportId}>`,
          `Tickets category: \`${created.ticketCategoryId}\``,
        ].join("\n"),
      });
    } catch (err) {
      await followUp(env.token, env.applicationId, interaction.token, {
        content: `Setup failed: ${err instanceof Error ? err.message : String(err)}`,
        flags: 64,
      });
    }
  });

  return deferred;
}

export async function runServerSetup(
  token: string,
  guildId: string,
  _applicationId: string,
) {
  const existing = await discordJson<DiscordChannel[]>(
    token,
    `/guilds/${guildId}/channels`,
  );

  const findByName = (name: string) =>
    existing.find((c) => c.name === name)?.id;

  let rulesId = findByName("rules");
  let welcomeId = findByName("welcome");
  let updatesId = findByName("updates");
  let supportId = findByName("support");
  let ticketCategoryId = existing.find((c) => c.name === "Support Tickets" && c.type === 4)?.id;

  if (!rulesId) {
    const ch = await discordJson<DiscordChannel>(token, `/guilds/${guildId}/channels`, {
      method: "POST",
      body: JSON.stringify({ name: "rules", type: 0, topic: "Server rules" }),
    });
    rulesId = ch.id;
    await discordJson(token, `/channels/${rulesId}/messages`, {
      method: "POST",
      body: JSON.stringify({ embeds: [rulesEmbed()] }),
    });
  }

  if (!welcomeId) {
    const ch = await discordJson<DiscordChannel>(token, `/guilds/${guildId}/channels`, {
      method: "POST",
      body: JSON.stringify({ name: "welcome", type: 0, topic: "Welcome" }),
    });
    welcomeId = ch.id;
  }

  if (!updatesId) {
    const ch = await discordJson<DiscordChannel>(token, `/guilds/${guildId}/channels`, {
      method: "POST",
      body: JSON.stringify({
        name: "updates",
        type: 0,
        topic: "kdesa.stream site updates",
      }),
    });
    updatesId = ch.id;
  }

  if (!supportId) {
    const ch = await discordJson<DiscordChannel>(token, `/guilds/${guildId}/channels`, {
      method: "POST",
      body: JSON.stringify({
        name: "support",
        type: 0,
        topic: "Open a ticket with /ticket",
      }),
    });
    supportId = ch.id;
    await discordJson(token, `/channels/${supportId}/messages`, {
      method: "POST",
      body: JSON.stringify({
        embeds: [{
          title: "Need help?",
          description: "Use `/ticket` anywhere in the server to open a private support channel.",
          color: 0x5865f2,
        }],
      }),
    });
  }

  if (!ticketCategoryId) {
    const cat = await discordJson<DiscordChannel>(token, `/guilds/${guildId}/channels`, {
      method: "POST",
      body: JSON.stringify({ name: "Support Tickets", type: 4 }),
    });
    ticketCategoryId = cat.id;
  }

  const welcome = replaceChannelPlaceholders(welcomeEmbed(), {
    rules: rulesId,
    support: supportId,
    updates: updatesId,
  });
  await discordJson(token, `/channels/${welcomeId}/messages`, {
    method: "POST",
    body: JSON.stringify({ embeds: [welcome] }),
  });

  return {
    rulesId: rulesId!,
    welcomeId: welcomeId!,
    updatesId: updatesId!,
    supportId: supportId!,
    ticketCategoryId: ticketCategoryId!,
  };
}

export async function handleComponent(
  interaction: Interaction,
  env: Env,
): Promise<Record<string, unknown>> {
  if (interaction.data?.custom_id !== "ticket_close") {
    return ephemeral("Unknown action.");
  }

  const user = interactionUser(interaction);
  if (!user || !interaction.channel_id) {
    return ephemeral("Could not resolve user.");
  }

  const fakeCommand: Interaction = {
    ...interaction,
    data: { name: "ticket-close" },
  };
  return handleTicketClose(fakeCommand, env, user);
}
